1	using DefaultEcs;
2	using DefaultEcs.System;
3	using Microsoft.Xna.Framework;
4	using Microsoft.Xna.Framework.Content;
5	using Microsoft.Xna.Framework.Graphics;
6	using Microsoft.Xna.Framework.Input;
7	using MonoDreams.Component;
8	using MonoDreams.Component.Cursor;
9	using MonoDreams.Component.Draw;
10	using MonoDreams.Demos.Screens;
11	using MonoDreams.Demos.UI;
12	using MonoDreams.Draw;
13	using MonoDreams.Extension;
14	using MonoDreams.Renderer;
15	using MonoDreams.Screen;
16	using MonoDreams.State;
17	using MonoDreams.System;
18	using MonoDreams.System.Camera;
19	using MonoDreams.System.Cursor;
20	using MonoDreams.System.Draw;
21	using MonoDreams.UI;
22	using MonoGame.Extended.BitmapFonts;
23	
24	namespace MonoDreams.Demo.Camera;
25	
26	/// Camera block demo. Move a red circle inside a boundary rectangle with WASD/arrows;
27	/// switch between five fixed camera targets (numbered 1–5, each shown as a hoverable
28	/// region in the world) and a follow mode (key 0). The "smooth lerp" toggle controls
29	/// the damping on <see cref="CameraFollowTargetComponent"/>: when on, the camera eases
30	/// toward its target (ball in follow mode, or the corresponding zone center in fixed
31	/// modes); when off, it snaps instantly.
32	public class CameraDemoScreen : IGameScreen
33	{
34	    private const float BoundaryHalfWidth = 380f;
35	    private const float BoundaryHalfHeight = 220f;
36	    private const float ZoneSize = 80f;
37	    private const float BallRadius = 20f;
38	    private const float MoveSpeed = 240f;
39	
40	    private const float DampingSmooth = 5f;
41	    private const float DampingInstant = 100f;
42	
43	    /// Keyboard-key 0..5 maps directly to enum index: 0 Follow, 1 TL, 2 TR,
44	    /// 3 BR, 4 BL, 5 Center. Reordering is intentional — clockwise around the
45	    /// boundary corners with Center last.
46	    public enum Mode { Follow, FixedTL, FixedTR, FixedBR, FixedBL, FixedCenter }
47	
48	    private readonly ContentManager _content;
49	    private readonly GraphicsDevice _graphicsDevice;
50	    private readonly MonoDreams.Component.Camera _camera;
51	    private readonly ViewportManager _viewportManager;
52	    private readonly SpriteBatch _spriteBatch;
53	    private readonly World _world;
54	    private readonly Dictionary<RenderTargetID, RenderTarget2D> _renderTargets;
55	    private readonly BitmapFont _font;
56	
57	    private ScreenController? _screenController;
58	    private Entity _ball;
59	    private Entity _cameraAnchor;
60	    private Entity _lerpToggle;
61	    private Entity _targetCross;
62	    private Mode _mode = Mode.Follow;
63	    private bool _lerpSmooth = true;
64	
65	    private readonly Dictionary<Mode, Entity> _sidebarButtons = new();
66	    private readonly Dictionary<Mode, Entity> _worldZoneButtons = new();
67	
68	    public ISystem<GameState> UpdateSystem { get; }
69	    public ISystem<GameState> DrawSystem { get; }
70	    public World World => _world;
71	
72	    public CameraDemoScreen(GraphicsDevice graphicsDevice, ContentManager content, MonoDreams.Component.Camera camera,
73	        ViewportManager viewportManager, SpriteBatch spriteBatch)
74	    {
75	        _graphicsDevice = graphicsDevice;
76	        _content = content;
77	        _camera = camera;
78	        _viewportManager = viewportManager;
79	        _spriteBatch = spriteBatch;
80	        _renderTargets = new Dictionary<RenderTargetID, RenderTarget2D>
81	        {
82	            { RenderTargetID.Main, new RenderTarget2D(graphicsDevice, viewportManager.VirtualWidth, viewportManager.VirtualHeight) },
83	            { RenderTargetID.UI, new RenderTarget2D(graphicsDevice, viewportManager.VirtualWidth, viewportManager.VirtualHeight) },
84	            { RenderTargetID.HUD, new RenderTarget2D(graphicsDevice, viewportManager.VirtualWidth, viewportManager.VirtualHeight) },
85	        };
86	        _font = content.Load<BitmapFont>("Fonts/UAV-OSD-Sans-Mono-72-White-fnt");
87	
88	        camera.Position = Vector2.Zero;
89	
90	        _world = new World();
91	        UpdateSystem = CreateUpdateSystem();
92	        DrawSystem = CreateDrawSystem();
93	    }
94	
95	    public void Load(ScreenController screenController, ContentManager content)
96	    {
97	        _screenController = screenController;
98	        _world.Subscribe<DemoButtonClicked>(OnButtonClicked);
99	
100	        var cursorTextures = new Dictionary<CursorType, Texture2D>
101	        {
102	            [CursorType.Default] = content.Load<Texture2D>("Cursor/default"),
103	            [CursorType.Pointer] = content.Load<Texture2D>("Cursor/pointer"),
104	            [CursorType.Hand] = content.Load<Texture2D>("Cursor/hand"),
105	        };
106	        MonoDreams.Cursor.Cursor.Create(_world, cursorTextures, RenderTargetID.HUD);
107	
108	        _cameraAnchor = _world.CreateEntity();
109	        _cameraAnchor.Set(new TransformComponent(Vector2.Zero));
110	
111	        CreateBoundary();
112	        CreateWorldZones();
113	        CreateBall();
114	        CreateTargetCross();
115	        CreateCameraCenterCross();
116	        BuildHud(content);
117	
118	        SetMode(_mode);
119	    }
120	
121	    // ─── public bridges for the keyboard system ───────────────────────────────
122	
123	    public void SetMode(Mode mode)
124	    {
125	        _mode = mode;
126	        foreach (var (m, btn) in _sidebarButtons) UpdateActive(btn, m == mode);
127	        foreach (var (m, btn) in _worldZoneButtons) UpdateActive(btn, m == mode);
128	
129	        if (mode == Mode.Follow)
130	        {
131	            if (_cameraAnchor.Has<CameraFollowTargetComponent>())
132	                _cameraAnchor.Remove<CameraFollowTargetComponent>();
133	            if (!_ball.Has<CameraFollowTargetComponent>())
134	                _ball.Set(new CameraFollowTargetComponent());
135	            ApplyDampingTo(_ball);
136	            ReparentTargetCross(_ball);
137	        }
138	        else
139	        {
140	            if (_ball.Has<CameraFollowTargetComponent>())
141	                _ball.Remove<CameraFollowTargetComponent>();
142	            var anchorTransform = _cameraAnchor.Get<TransformComponent>();
143	            anchorTransform.Position = ModeCameraTarget(mode);
144	            if (!_cameraAnchor.Has<CameraFollowTargetComponent>())
145	                _cameraAnchor.Set(new CameraFollowTargetComponent());
146	            ApplyDampingTo(_cameraAnchor);
147	            ReparentTargetCross(_cameraAnchor);
148	
149	            if (!_lerpSmooth) _camera.Position = anchorTransform.Position;
150	        }
151	    }
152	
153	    private void ReparentTargetCross(Entity newParent)
154	    {
155	        if (!_targetCross.IsAlive) return;
156	        // SetParent overwrites ChildOfComponent + transform.Parent in place;
157	        // we deliberately skip RemoveParent so the cross's LOCAL position stays
158	        // at (0,0). RemoveParent snapshots the current world position into the
159	        // local one, which would double the offset on the next reparent.
160	        _targetCross.SetParent(newParent);
161	        _targetCross.Get<TransformComponent>().Position = Vector2.Zero;
162	    }
163	
164	    public void GoBackToLauncher() => _screenController?.LoadScreen(DemoScreens.Launcher);
165	
166	    public void ToggleLerp()
167	    {
168	        if (!_lerpToggle.IsAlive || !_lerpToggle.Has<ToggleSwitchComponent>()) return;
169	        var sw = _lerpToggle.Get<ToggleSwitchComponent>();
170	        sw.On = !sw.On;
171	        _lerpSmooth = sw.On;
172	        _lerpToggle.Set(sw);
173	
174	        if (_ball.Has<CameraFollowTargetComponent>()) ApplyDampingTo(_ball);
175	        if (_cameraAnchor.Has<CameraFollowTargetComponent>())
176	        {
177	            ApplyDampingTo(_cameraAnchor);
178	            if (!_lerpSmooth) _camera.Position = _cameraAnchor.Get<TransformComponent>().Position;
179	        }
180	    }
181	
182	    private void ApplyDampingTo(Entity target)
183	    {
184	        if (!target.Has<CameraFollowTargetComponent>()) return;
185	        var ft = target.Get<CameraFollowTargetComponent>();
186	        ft.DampingX = _lerpSmooth ? DampingSmooth : DampingInstant;
187	        ft.DampingY = _lerpSmooth ? DampingSmooth : DampingInstant;
188	        ft.MaxDistanceX = 10000f;
189	        ft.MaxDistanceY = 10000f;
190	    }
191	
192	    private static void UpdateActive(Entity entity, bool active)
193	    {
194	        if (!entity.IsAlive || !entity.Has<DemoButtonComponent>()) return;
195	        ref var b = ref entity.Get<DemoButtonComponent>();
196	        b.IsActive = active;
197	    }
198	
199	    // Camera centers exactly on the zone the user clicked. Zone centers sit at the
200	    // corners offset by half the zone size so the zone sprite is fully on-screen.
201	    private static Vector2 ModeCameraTarget(Mode m)
202	    {
203	        var halfZone = ZoneSize / 2f;
204	        return m switch
205	        {
206	            Mode.FixedTL     => new Vector2(-BoundaryHalfWidth + halfZone, -BoundaryHalfHeight + halfZone),
207	            Mode.FixedTR     => new Vector2( BoundaryHalfWidth - halfZone, -BoundaryHalfHeight + halfZone),
208	            Mode.FixedCenter => Vector2.Zero,
209	            Mode.FixedBL     => new Vector2(-BoundaryHalfWidth + halfZone,  BoundaryHalfHeight - halfZone),
210	            Mode.FixedBR     => new Vector2( BoundaryHalfWidth - halfZone,  BoundaryHalfHeight - halfZone),
211	            _                => Vector2.Zero,
212	        };
213	    }
214	
215	    private static Vector2 ZoneTopLeft(Mode m)
216	    {
217	        var half = ZoneSize / 2f;
218	        return m switch
219	        {
220	            Mode.FixedTL     => new Vector2(-BoundaryHalfWidth,             -BoundaryHalfHeight),
221	            Mode.FixedTR     => new Vector2( BoundaryHalfWidth - ZoneSize,  -BoundaryHalfHeight),
222	            Mode.FixedCenter => new Vector2(-half, -half),
223	            Mode.FixedBL     => new Vector2(-BoundaryHalfWidth,              BoundaryHalfHeight - ZoneSize),
224	            Mode.FixedBR     => new Vector2( BoundaryHalfWidth - ZoneSize,   BoundaryHalfHeight - ZoneSize),
225	            _ => Vector2.Zero,
226	        };
227	    }
228	
229	    // ─── button click routing ────────────────────────────────────────────────
230	
231	    private void OnButtonClicked(in DemoButtonClicked msg)
232	    {
233	        switch (msg.Id)
234	        {
235	            case DemoHeader.BackId: _screenController?.LoadScreen(DemoScreens.Launcher); break;
236	            case DemoHeader.ExitId: _screenController?.Game.Exit(); break;
237	            case "mode.follow": SetMode(Mode.Follow); break;
238	            case "mode.tl":     SetMode(Mode.FixedTL); break;
239	            case "mode.tr":     SetMode(Mode.FixedTR); break;
240	            case "mode.center": SetMode(Mode.FixedCenter); break;
241	            case "mode.bl":     SetMode(Mode.FixedBL); break;
242	            case "mode.br":     SetMode(Mode.FixedBR); break;
243	            case "toggle.lerp": ToggleLerp(); break;
244	        }
245	    }
246	
247	    // ─── world entities ──────────────────────────────────────────────────────
248	
249	    private void CreateBoundary()
250	    {
251	        var bounds = new Rectangle(
252	            -(int)BoundaryHalfWidth, -(int)BoundaryHalfHeight,
253	            (int)BoundaryHalfWidth * 2, (int)BoundaryHalfHeight * 2);
254	
255	        var boundary = _world.CreateEntity();
256	        boundary.Set(new TransformComponent(Vector2.Zero));
257	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.2f };
258	        draw.SetMeshData(new RectangleOutlineMeshGenerator(bounds, thickness: 2f, color: SproutPalette.TextLight));
259	        boundary.Set(draw);
260	        boundary.Set<VisibleComponent>();
261	    }
262	
263	    private void CreateWorldZones()
264	    {
265	        // Numbering matches the keyboard digits — 1 TL, 2 TR, 3 BR, 4 BL, 5 Center.
266	        CreateWorldZone(Mode.FixedTL,     "1", "mode.tl");
267	        CreateWorldZone(Mode.FixedTR,     "2", "mode.tr");
268	        CreateWorldZone(Mode.FixedBR,     "3", "mode.br");
269	        CreateWorldZone(Mode.FixedBL,     "4", "mode.bl");
270	        CreateWorldZone(Mode.FixedCenter, "5", "mode.center");
271	    }
272	
273	    private void CreateWorldZone(Mode mode, string label, string id)
274	    {
275	        var topLeft = ZoneTopLeft(mode);
276	        var sharedTransform = new TransformComponent(topLeft);
277	
278	        var container = _world.CreateEntity();
279	        container.Set(sharedTransform);
280	
281	        const float labelScale = 0.50f;
282	        var measured = _font.MeasureString(label);
283	        var labelSize = new Vector2(measured.Width * labelScale, measured.Height * labelScale);
284	        var labelOffset = new Vector2((ZoneSize - labelSize.X) / 2f, (ZoneSize - labelSize.Y) / 2f);
285	        var labelEntity = _world.CreateEntity();
286	        labelEntity.Set(new TransformComponent(labelOffset));
287	        labelEntity.SetParent(container);
288	        labelEntity.Set(new DynamicTextComponent
289	        {
290	            Target = RenderTargetID.Main,
291	            LayerDepth = 0.35f,
292	            TextContent = label,
293	            Font = _font,
294	            Color = SproutPalette.TextLight,
295	            Scale = labelScale,
296	            IsRevealed = true,
297	            VisibleCharacterCount = int.MaxValue,
298	        });
299	        labelEntity.Set<VisibleComponent>();
300	
301	        var outline = _world.CreateEntity();
302	        outline.Set(sharedTransform);
303	        outline.Set(new SimpleButtonComponent
304	        {
305	            Size = new Vector2(ZoneSize, ZoneSize),
306	            LineThickness = 1.5f,
307	            Color = SproutPalette.TextLight,
308	            TextEntity = labelEntity,
309	            Target = RenderTargetID.Main,
310	        });
311	        outline.Set(new DemoButtonComponent
312	        {
313	            Id = id,
314	            DefaultColor = SproutPalette.TextLight,
315	            HoveredColor = SproutPalette.TextHover,
316	            ActiveColor = SproutPalette.TextSelected,
317	        });
318	        outline.Set<VisibleComponent>();
319	        _worldZoneButtons[mode] = outline;
320	    }
321	
322	    private void CreateBall()
323	    {
324	        _ball = _world.CreateEntity();
325	        _ball.Set(new TransformComponent(Vector2.Zero));
326	        _ball.Set(new PlayerBallTag());
327	        // 0.97 puts the ball above the world-zone button outlines (those get
328	        // LayerDepth=0.95 from ButtonMeshPrepSystem) so the ball doesn't get
329	        // clipped by a zone's outline as it crosses through.
330	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.97f };
331	        draw.SetMeshData(new CircleMeshGenerator(Vector2.Zero, BallRadius, SproutPalette.Crimson, segments: 32));
332	        _ball.Set(draw);
333	        _ball.Set<VisibleComponent>();
334	
335	        // Clickable hit-area for the ball — child entity offset to the ball's
336	        // top-left so the bounds-based hit test wraps the circle. Clicking the
337	        // ball switches to follow mode.
338	        var hitArea = _world.CreateEntity();
339	        hitArea.Set(new TransformComponent(new Vector2(-BallRadius, -BallRadius)));
340	        hitArea.SetParent(_ball);
341	        hitArea.Set(new SimpleButtonComponent
342	        {
343	            Size = new Vector2(BallRadius * 2, BallRadius * 2),
344	            LineThickness = 0f,
345	            Color = Color.Transparent,
346	            FillColor = Color.Transparent,
347	            TextEntity = null,
348	            Target = RenderTargetID.Main,
349	        });
350	        hitArea.Set(new DemoButtonComponent
351	        {
352	            Id = "mode.follow",
353	            DefaultColor = Color.Transparent,
354	            HoveredColor = Color.Transparent,
355	            ActiveColor = Color.Transparent,
356	        });
357	        hitArea.Set<VisibleComponent>();
358	    }
359	
360	    /// Green cross marking where the camera *wants* to be. Parented to whichever
361	    /// entity currently has <see cref="CameraFollowTargetComponent"/> so it sits
362	    /// exactly at the target — when the camera lerps, the green cross stays put
363	    /// and the screen-center yellow cross drifts toward it.
364	    private void CreateTargetCross()
365	    {
366	        _targetCross = _world.CreateEntity();
367	        _targetCross.Set(new TransformComponent(Vector2.Zero));
368	        // 0.98 puts the cross above the ball (0.97) so the target marker is
369	        // never occluded when it sits on the ball in follow mode.
370	        var draw = new DrawComponent { Target = RenderTargetID.Main, LayerDepth = 0.98f };
371	        draw.SetMeshData(CrossMesh(armPixels: 16, thicknessPixels: 3, color: Color.Black));
372	        _targetCross.Set(draw);
373	        _targetCross.Set<VisibleComponent>();
374	    }
375	
376	    /// Yellow cross drawn on HUD at the screen center — marks the point the
377	    /// camera is currently looking at. Camera-independent (HUD is not affected
378	    /// by the view transform), so this stays put even as the world scrolls.
379	    private void CreateCameraCenterCross()
380	    {
381	        var entity = _world.CreateEntity();
382	        entity.Set(new TransformComponent(new Vector2(
383	            _viewportManager.VirtualWidth / 2f,
384	            _viewportManager.VirtualHeight / 2f)));
385	        var draw = new DrawComponent { Target = RenderTargetID.HUD, LayerDepth = 0.92f };
386	        draw.SetMeshData(CrossMesh(armPixels: 14, thicknessPixels: 3, color: Color.White));
387	        entity.Set(draw);
388	        entity.Set<VisibleComponent>();
389	    }
390	
391	    private static CompositeMeshGenerator CrossMesh(int armPixels, int thicknessPixels, Color color)
392	    {
393	        var halfT = thicknessPixels / 2;
394	        return new CompositeMeshGenerator()
395	            .Add(new FilledRectangleMeshGenerator(
396	                new Rectangle(-armPixels, -halfT, armPixels * 2, thicknessPixels), color))
397	            .Add(new FilledRectangleMeshGenerator(
398	                new Rectangle(-halfT, -armPixels, thicknessPixels, armPixels * 2), color));
399	    }
400	
401	    // ─── HUD ────────────────────────────────────────────────────────────────
402	
403	    private void BuildHud(ContentManager content)
404	    {
405	        var squareButtons = content.Load<Texture2D>("SproutLands/Buttons/square_26x26");
406	        var settingsSheet = content.Load<Texture2D>("SproutLands/Buttons/settings_buttons");
407	
408	        DemoHeader.Build(
409	            _world, _viewportManager, _font, squareButtons,
410	            title: "camera",
411	            descriptionLines: new[]
412	            {
413	                "Use keyboard keys 0 to 5 to switch the camera target",
414	                "and the L key to toggle camera lerp.",
415	                "Use the WASD keys to control the red dot.",
416	            });
417	
418	        BuildSidebar(squareButtons, settingsSheet);
419	    }
420	
421	    private void BuildSidebar(Texture2D squareButtons, Texture2D settingsSheet)
422	    {
423	        var capStyle = new KeyCapStyle
424	        {
425	            SpriteSheet = squareButtons,
426	            DefaultSource = SproutSquareButtons.CreamLight,
427	            HoverSource   = SproutSquareButtons.CreamDark,
428	            ActiveSource  = SproutSquareButtons.TanDark,
429	            // 42 matches the lerp toggle pill width so all sidebar elements
430	            // line up on a shared left edge.
431	            CapPixels = 42,
432	            CapLabelScale = 0.22f,
433	            CapLabelColor = SproutPalette.WarmBrown,
434	        };
435	        var rowStyle = new KeyRowStyle
436	        {
437	            LabelColor = SproutPalette.TextLight,
438	            HoverColor = SproutPalette.TextHover,
439	            ActiveColor = SproutPalette.TextSelected,
440	            LabelScale = 0.18f,
441	            Gap = 10f,
442	            BackgroundColor = SproutPalette.DarkBgSecondary,
443	            HoverBackgroundColor = SproutPalette.DarkBgSecondary,
444	            ActiveBackgroundColor = SproutPalette.DarkBgSecondary,
445	            BackgroundPaddingX = 10f,
446	            BackgroundPaddingY = 6f,
447	        };
448	
449	        (Entity Container, Entity Outline, Vector2 Size) Row(string id, string key, string label) =>
450	            _world.CreateKeyRow(id, key, label, _font, capStyle, rowStyle, layerDepth: 0.96f);
451	
452	        // Order: 0 follow, 1 TL, 2 TR, 3 BR, 4 BL, 5 center.
453	        var follow = Row("mode.follow", "0", "follow red dot");
454	        var tl     = Row("mode.tl",     "1", "top-left");
455	        var tr     = Row("mode.tr",     "2", "top-right");
456	        var br     = Row("mode.br",     "3", "bottom-right");
457	        var bl     = Row("mode.bl",     "4", "bottom-left");
458	        var center = Row("mode.center", "5", "center");
459	
460	        // Toggle pill native is 28x18 (aspect ~1.56). Draw at 42x27 = native × 1.5
461	        // so the aspect ratio is preserved and the pill scales to match the cap chip.
462	        var lerp = _world.CreateToggleRow(
463	            id: "toggle.lerp",
464	            rowLabel: "smooth lerp",
465	            font: _font,
466	            toggleSheet: settingsSheet,
467	            offSource: SproutSettings.ToggleOff,
468	            onSource: SproutSettings.ToggleOn,
469	            initiallyOn: _lerpSmooth,
470	            toggleSize: new Vector2(42, 27),
471	            row: rowStyle,
472	            layerDepth: 0.96f);
473	
474	        _sidebarButtons[Mode.Follow]      = follow.Outline;
475	        _sidebarButtons[Mode.FixedTL]     = tl.Outline;
476	        _sidebarButtons[Mode.FixedTR]     = tr.Outline;
477	        _sidebarButtons[Mode.FixedBR]     = br.Outline;
478	        _sidebarButtons[Mode.FixedBL]     = bl.Outline;
479	        _sidebarButtons[Mode.FixedCenter] = center.Outline;
480	        _lerpToggle = lerp.Outline;
481	
482	        const float rowGap = 6f;       // gap BETWEEN per-row backgrounds
483	        const float groupGap = 16f;    // larger gap before the lerp toggle group
484	
485	        new AutoLayoutBuilder(_world, _viewportManager)
486	            .CreateRoot(ScreenAnchor.TopLeft, RenderTargetID.HUD)
487	            .Direction(LayoutDirection.Vertical)
488	            .Gap(rowGap)
489	            // Screen-root stacks roots vertically, so the sidebar already lands
490	            // below the header automatically — just add a small breathing pad.
491	            .Padding(20 /* top */, 12 /* right */, 12 /* bottom */, 12 /* left */)
492	            .AlignCross(CrossAxisAlignment.Start)
493	            .AddSlot(slot => slot.Attach(follow.Container).MeasureWith(_ => follow.Size))
494	            .AddSlot(slot => slot.Attach(tl.Container).MeasureWith(_ => tl.Size))
495	            .AddSlot(slot => slot.Attach(tr.Container).MeasureWith(_ => tr.Size))
496	            .AddSlot(slot => slot.Attach(br.Container).MeasureWith(_ => br.Size))
497	            .AddSlot(slot => slot.Attach(bl.Container).MeasureWith(_ => bl.Size))
498	            .AddSlot(slot => slot.Attach(center.Container).MeasureWith(_ => center.Size))
499	            .AddSlot(slot => slot.Attach(_world.CreateEntity()).MeasureWith(_ => new Vector2(0, groupGap - rowGap)))
500	            .AddSlot(slot => slot.Attach(lerp.Container).MeasureWith(_ => lerp.Size))
501	            .Build();
502	    }
503	
504	    // ─── pipeline ────────────────────────────────────────────────────────────
505	
506	    private SequentialSystem<GameState> CreateUpdateSystem()
507	    {
508	        return new SequentialSystem<GameState>(
509	            new CursorInputSystem(_world),
510	            new IntrinsicSizingSystem(_world),
511	            new AutoLayoutSystem(_world, _viewportManager),
512	            new DemoButtonInteractionSystem(_world),
513	            new DemoIconRecolorSystem(_world),
514	            new ToggleSwitchSystem(_world),
515	            new PlayerBallMovementSystem(_world, BoundaryHalfWidth, BoundaryHalfHeight, BallRadius, MoveSpeed),
516	            new CameraDemoInputSystem(this),
517	            new CameraFollowSystem(_world, _camera),
518	            new HierarchySystem(_world),
519	            new CursorPositionSystem(_world, _camera, _viewportManager),
520	            new CursorDrawPrepSystem(_world));
521	    }
522	
523	    private SequentialSystem<GameState> CreateDrawSystem()
524	    {
525	        return new SequentialSystem<GameState>(
526	            new SpritePrepSystem(_world, _graphicsDevice, pixelPerfectRendering: false),
527	            new TextPrepSystem(_world, pixelPerfectRendering: false),
528	            new MeshPrepSystem(_world),
529	            new ButtonMeshPrepSystem(_world),
530	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _camera, _renderTargets, _world),
531	            new FinalDrawSystem(_spriteBatch, _graphicsDevice, _viewportManager, _camera, _renderTargets));
532	    }
533	
534	    public void Dispose()
535	    {
536	        UpdateSystem.Dispose();
537	        DrawSystem.Dispose();
538	        foreach (var rt in _renderTargets.Values) rt.Dispose();
539	        _world.Dispose();
540	        GC.SuppressFinalize(this);
541	    }
542	}
