544	/// Tag identifying the player-controlled circle in the camera demo.
545	public struct PlayerBallTag { }
546	
547	/// Reads keyboard input (WASD + arrows) and translates the tagged player entity,
548	/// clamping its position so the ball stays inside the boundary rectangle.
549	[With(typeof(PlayerBallTag), typeof(TransformComponent))]
550	public class PlayerBallMovementSystem : AEntitySetSystem<GameState>
551	{
552	    private readonly float _halfWidth;
553	    private readonly float _halfHeight;
554	    private readonly float _radius;
555	    private readonly float _speed;
556	
557	    public PlayerBallMovementSystem(World world, float halfWidth, float halfHeight, float radius, float speed)
558	        : base(world)
559	    {
560	        _halfWidth = halfWidth;
561	        _halfHeight = halfHeight;
562	        _radius = radius;
563	        _speed = speed;
564	    }
565	
566	    protected override void Update(GameState state, in Entity entity)
567	    {
568	        var keyboard = Keyboard.GetState();
569	        var dir = Vector2.Zero;
570	        if (keyboard.IsKeyDown(Keys.A) || keyboard.IsKeyDown(Keys.Left))  dir.X -= 1f;
571	        if (keyboard.IsKeyDown(Keys.D) || keyboard.IsKeyDown(Keys.Right)) dir.X += 1f;
572	        if (keyboard.IsKeyDown(Keys.W) || keyboard.IsKeyDown(Keys.Up))    dir.Y -= 1f;
573	        if (keyboard.IsKeyDown(Keys.S) || keyboard.IsKeyDown(Keys.Down))  dir.Y += 1f;
574	        if (dir != Vector2.Zero) dir.Normalize();
575	
576	        var transform = entity.Get<TransformComponent>();
577	        var next = transform.Position + dir * _speed * state.Time;
578	        next.X = MathHelper.Clamp(next.X, -_halfWidth + _radius, _halfWidth - _radius);
579	        next.Y = MathHelper.Clamp(next.Y, -_halfHeight + _radius, _halfHeight - _radius);
580	        transform.Position = next;
581	    }
582	}
583	
584	/// Polls the keyboard for camera-mode shortcuts (0–5, L) and forwards them
585	/// to the owning <see cref="CameraDemoScreen"/>. Edge-triggered: each key press
586	/// fires once per release-then-press cycle.
587	public class CameraDemoInputSystem : ISystem<GameState>
588	{
589	    private readonly CameraDemoScreen _screen;
590	    private KeyboardState _previous;
591	    public bool IsEnabled { get; set; } = true;
592	
593	    public CameraDemoInputSystem(CameraDemoScreen screen)
594	    {
595	        _screen = screen;
596	        _previous = Keyboard.GetState();
597	    }
598	
599	    public void Update(GameState state)
600	    {
601	        if (!IsEnabled) return;
602	        var current = Keyboard.GetState();
603	        bool Pressed(Keys k) => current.IsKeyDown(k) && !_previous.IsKeyDown(k);
604	
605	        if (Pressed(Keys.D0) || Pressed(Keys.NumPad0)) _screen.SetMode(CameraDemoScreen.Mode.Follow);
606	        if (Pressed(Keys.D1) || Pressed(Keys.NumPad1)) _screen.SetMode(CameraDemoScreen.Mode.FixedTL);
607	        if (Pressed(Keys.D2) || Pressed(Keys.NumPad2)) _screen.SetMode(CameraDemoScreen.Mode.FixedTR);
608	        if (Pressed(Keys.D3) || Pressed(Keys.NumPad3)) _screen.SetMode(CameraDemoScreen.Mode.FixedBR);
609	        if (Pressed(Keys.D4) || Pressed(Keys.NumPad4)) _screen.SetMode(CameraDemoScreen.Mode.FixedBL);
610	        if (Pressed(Keys.D5) || Pressed(Keys.NumPad5)) _screen.SetMode(CameraDemoScreen.Mode.FixedCenter);
611	        if (Pressed(Keys.L)) _screen.ToggleLerp();
612	        if (Pressed(Keys.Escape)) _screen.GoBackToLauncher();
613	
614	        _previous = current;
615	    }
616	
617	    public void Dispose() => GC.SuppressFinalize(this);
618	}
