                for (var i = 0; i < lines.Length; i++)
                {
                    spriteBatch.DrawString(
                        element.Font,
                        lines[i],
                        element.Position + new Vector2(0f, i * lineAdvance),
                        element.Color,
                        element.Rotation,
                        element.Origin,
                        element.Scale,
                        SpriteEffects.None,
                        element.LayerDepth);
                }
                break;

            case DrawElementType.NinePatch:
                // NinePatch handled by SpritePrepSystem creating 9 sprite elements
                break;

            case DrawElementType.Mesh:
                // Handled separately in DrawSingleMesh via RenderInterleaved
                break;
        }
    }

    public void Dispose()
    {
        _basicEffect?.Dispose();
    }

    public bool IsEnabled { get; set; } = true;
}

