private BasicEffect? _basicEffect;

// One EntitySet per render target, built lazily and reused for the
// lifetime of the system. AsSet() registers subscriptions on the World
// that the World keeps alive forever — building a fresh set every frame
// (as this used to) leaks an EntitySet + its subscriptions per target per
// frame, so memory climbs even on a static scene. See premise
// "Per-target draw sets are built once, not per frame".
private readonly Dictionary<RenderTargetID, EntitySet> _drawSets = new();

private EntitySet GetDrawSet(RenderTargetID target)
{
    if (_drawSets.TryGetValue(target, out var set))
        return set;

    var queryBuilder = world.GetEntities()
        .With((in DrawComponent e) => e.Target == target);

    // Main target: respect CullingSystem visibility. HUD/UI: always render.
    if (target == RenderTargetID.Main)
        queryBuilder = queryBuilder.With<VisibleComponent>();

    set = queryBuilder.AsSet();
    _drawSets[target] = set;
    return set;
}

